head.script:

scwin.onpageload = function() {
	var options = {
		  title : "tab1"
		, src : "wframe_setSrc_onpageonload_WESD-1474_(WSQ-5441)_tab1.xml"
		, windowTitle : "탭1"
		, windowId : "00001"
		, openAction : "existWindow" // 미지정시 id가 동일 창이 있으면 확인창 띄움. existWindow : 기존 탭을 갱신 / newWindow : 항상 새로운 창을 생성 / selectWindow : id가 동일한 창이 있으면 그 윈도우를 선택
		, frameMode : "wframe"			
	}


	$p.top().wdc_layout.createWindow(options);	
};

scwin.onpageunload = function() {

};


scwin.trigger1_onclick = function(e) {
	var options = {
		  title : "tab2"
		, src : "wframe_setSrc_onpageonload_WESD-1474_(WSQ-5441)_tab2.xml"
		, windowTitle : "탭2"
		, windowId : "00002"
		, openAction : "existWindow" // 미지정시 id가 동일 창이 있으면 확인창 띄움. existWindow : 기존 탭을 갱신 / newWindow : 항상 새로운 창을 생성 / selectWindow : id가 동일한 창이 있으면 그 윈도우를 선택
		, frameMode : "wframe"			
	}


	$p.top().wdc_layout.createWindow(options);	
};

scwin.checkVal = function() {
	return localStorage.getItem('log') == 'sub2';
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
	WebSquare.wUnit.addCommand("pause", "400");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_layout_subWindow1_wframe_gen_list_0_appname').click()");
	WebSquare.wUnit.addCommand("pause", "400");		
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand("pause", "500");
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
localStorage.removeItem("log");
